import numpy as np

def clean(df):
    df = df.copy()
    df = df.drop_duplicates()
    df['species'] = df['species'].replace('Adeile', 'Adelie')
    df.loc[(df['body_mass_g'] < 2500) | (df['body_mass_g'] > 6500), 'body_mass_g'] = np.nan
    return df

def answer(df):
    return df.groupby('species')['body_mass_g'].mean().to_dict()
